// Pre-resolve DNS and reject private / link-local / metadata ranges before fetch()
const { address } = await Deno.resolveDns(host, 'A');
if (isPrivateRange(address)) return 400;

const { data: claimData } = await supabase.auth.getClaims(token);
if (!claimData?.claims?.sub) return 401;
// per-user rate limit via seo_events (10/hour)

DROP POLICY "Authenticated can view allowlist audit log" ON public.host_allowlist_requests;
CREATE POLICY "Admins can view allowlist audit log"
  ON public.host_allowlist_requests FOR SELECT
  TO authenticated
  USING (public.has_role(auth.uid(), 'admin'::public.app_role));
